pub enum Reading {
    Offline,
    Sample(i32, u64),
}

pub fn describe(r: &Reading) -> String {
    match r {
        Reading::Offline => String::from("offline"),
        Reading::Sample(value) => format!("{value} at t=?"),
    }
}

pub fn run() -> (String, String) {
    (
        describe(&Reading::Offline),
        describe(&Reading::Sample(22, 5)),
    )
}

