pub enum Event {
    Click { x: i32, y: i32 },
    Move { x: i32, y: i32 },
    Key(char),
}

pub fn horizontal(e: &Event) -> i32 {
    match e {
        Event::Click { x, .. } | Event::Move { y, .. } => *x,
        Event::Key(_) => 0,
    }
}

pub fn run() -> Vec<i32> {
    vec![
        horizontal(&Event::Click { x: 3, y: 9 }),
        horizontal(&Event::Move { x: 7, y: 1 }),
        horizontal(&Event::Key('q')),
    ]
}

