exercises.starter:
pub enum State {
    Idle,
    Running { ticks: u32 },
    Done(u32),
}

pub enum Event {
    Start,
    Tick,
    Stop,
}

pub fn step(state: State, ev: Event) -> State {
    match (state, ev) {
        (State::Idle, Event::Start) => State::Running { ticks: 0 },
        (State::Running { ticks }, Event::Tick) => State::Running { ticks: ticks + 1 },
        (State::Running { ticks }, Event::Stop) => State::Done(ticks),
    }
}

pub fn run() -> u32 {
    let mut s = State::Idle;
    for ev in [Event::Tick, Event::Start, Event::Tick, Event::Tick, Event::Stop, Event::Start] {
        s = step(s, ev);
    }
    match s {
        State::Done(n) => n,
        _ => 999,
    }
}

exercises.tests:
#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn ignores_impossible_transitions() {
        assert_eq!(run(), 2);
    }
}

exercises.solution:
pub enum State {
    Idle,
    Running { ticks: u32 },
    Done(u32),
}

pub enum Event {
    Start,
    Tick,
    Stop,
}

pub fn step(state: State, ev: Event) -> State {
    match (state, ev) {
        (State::Idle, Event::Start) => State::Running { ticks: 0 },
        (State::Running { ticks }, Event::Tick) => State::Running { ticks: ticks + 1 },
        (State::Running { ticks }, Event::Stop) => State::Done(ticks),
        (s, _) => s,
    }
}

pub fn run() -> u32 {
    let mut s = State::Idle;
    for ev in [Event::Tick, Event::Start, Event::Tick, Event::Tick, Event::Stop, Event::Start] {
        s = step(s, ev);
    }
    match s {
        State::Done(n) => n,
        _ => 999,
    }
}
